import java.util.*; import java.io.*; public class Main { public static void main(String[] args) throws IOException { BufferedReader br = new BufferedReader(new InputStreamReader(System.in)); StringTokenizer st = new StringTokenizer(br.readLine()); int t = Integer.parseInt(st.nextToken()); while (t-- > 0) { String line = br.readLine(); while (line != null && line.trim().isEmpty()) line = br.readLine(); if (line == null) break; int n = Integer.parseInt(line.trim()); int[][] triangle = new int[n][n]; for (int i = 0; i < n; i++) { st = new StringTokenizer(br.readLine()); for (int j = 0; j <= i; j++) { triangle[i][j] = Integer.parseInt(st.nextToken()); } } for (int i = n - 2; i >= 0; i--) { for (int j = 0; j <= i; j++) { triangle[i][j] += Math.max(triangle[i + 1][j], triangle[i + 1][j + 1]); } } System.out.println(triangle[0][0]); } } }